#!/usr/bin/env node
// Derive the fastlane-layout Play listing metadata from the human-reviewable
// store package. `apps/mobile/store/` stays the source people edit and review;
// `apps/mobile/fastlane/metadata/android/<locale>/` is generated by this script,
// committed, and read verbatim by scripts/play-publish-listing.sh and
// scripts/play-publish.sh (release notes).
//
//   node scripts/sync-play-metadata.mjs            # regenerate
//   node scripts/sync-play-metadata.mjs --check    # fail when the committed output is stale
//
// Every asset is validated against the Play Console limits before it is copied
// so a bad source fails here, in the tree, rather than at the API boundary.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const DEFAULT_STORE_DIR = path.join(REPO, 'apps', 'mobile', 'store');
export const DEFAULT_OUT_DIR = path.join(REPO, 'apps', 'mobile', 'fastlane', 'metadata', 'android');
export const DEFAULT_LOCALE = 'en-US';

// Play Console limits (Store listing → Main store listing; release notes per language).
export const LIMITS = { title: 30, shortDescription: 80, fullDescription: 4000, releaseNotes: 500 };

function rel(file) {
  const relative = path.relative(REPO, file);
  return relative.startsWith('..') ? file : relative;
}

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const PNG_RGB = 2;
const PNG_RGBA = 6;

export function readPngHeader(bytes) {
  if (bytes.length < 29 || !bytes.subarray(0, 8).equals(PNG_SIGNATURE) || bytes.toString('latin1', 12, 16) !== 'IHDR') {
    throw new Error('not a PNG file');
  }
  return {
    width: bytes.readUInt32BE(16),
    height: bytes.readUInt32BE(20),
    bitDepth: bytes[24],
    colorType: bytes[25],
  };
}

function describe(header) {
  const color = { [PNG_RGB]: 'RGB', [PNG_RGBA]: 'RGBA' }[header.colorType] ?? `color type ${header.colorType}`;
  return `${header.width}x${header.height} ${header.bitDepth}-bit ${color}`;
}

function assertPng(file, expect) {
  const header = readPngHeader(fs.readFileSync(file));
  const problems = [];
  if (expect.width !== undefined && (header.width !== expect.width || header.height !== expect.height)) {
    problems.push(`must be ${expect.width}x${expect.height}`);
  }
  if (header.bitDepth !== 8) problems.push('must be 8 bits per channel');
  if (expect.colorType === PNG_RGBA && header.colorType !== PNG_RGBA) problems.push('must be a 32-bit PNG with an alpha channel');
  if (expect.colorType === PNG_RGB && header.colorType !== PNG_RGB) problems.push('must be a 24-bit PNG without an alpha channel');
  if (expect.screenshot) {
    const min = Math.min(header.width, header.height);
    const max = Math.max(header.width, header.height);
    if (min < 320 || max > 3840) problems.push('each side must be between 320 and 3840 pixels');
    if (max > 2 * min) problems.push('the long side may not exceed twice the short side');
  }
  if (problems.length > 0) {
    throw new Error(`${rel(file)} is ${describe(header)}; ${problems.join('; ')}`);
  }
  return header;
}

function readText(file, limit, label) {
  if (!fs.existsSync(file)) throw new Error(`missing ${rel(file)}`);
  const text = fs.readFileSync(file, 'utf8').replace(/\s+$/u, '');
  if (text.length === 0) throw new Error(`${rel(file)} is empty`);
  if (text.length > limit) {
    throw new Error(`${label} is ${text.length} characters; Play allows ${limit} (${rel(file)})`);
  }
  return `${text}\n`;
}

// Returns the planned output as { relativePath: Buffer } without touching disk.
export function planPlayMetadata({ storeDir = DEFAULT_STORE_DIR, locale = DEFAULT_LOCALE } = {}) {
  const listing = path.join(storeDir, 'listing', locale);
  const assets = path.join(storeDir, 'assets');
  const screenshots = path.join(storeDir, 'screenshots');
  const plan = new Map();

  plan.set(`${locale}/title.txt`, Buffer.from(readText(path.join(listing, 'title.txt'), LIMITS.title, 'title')));
  plan.set(
    `${locale}/short_description.txt`,
    Buffer.from(readText(path.join(listing, 'short-description.txt'), LIMITS.shortDescription, 'short description')),
  );
  plan.set(
    `${locale}/full_description.txt`,
    Buffer.from(readText(path.join(listing, 'full-description.txt'), LIMITS.fullDescription, 'full description')),
  );
  plan.set(
    `${locale}/changelogs/default.txt`,
    Buffer.from(readText(path.join(listing, 'release-notes.txt'), LIMITS.releaseNotes, 'release notes')),
  );

  const icon = path.join(assets, 'store-icon-512.png');
  assertPng(icon, { width: 512, height: 512, colorType: PNG_RGBA });
  plan.set(`${locale}/images/icon.png`, fs.readFileSync(icon));

  const feature = path.join(assets, 'feature-graphic-1024x500.png');
  assertPng(feature, { width: 1024, height: 500, colorType: PNG_RGB });
  plan.set(`${locale}/images/featureGraphic.png`, fs.readFileSync(feature));

  const shots = fs.existsSync(screenshots)
    ? fs.readdirSync(screenshots).filter((name) => name.endsWith('.png')).sort()
    : [];
  if (shots.length < 2 || shots.length > 8) {
    throw new Error(`${rel(screenshots)} holds ${shots.length} PNG screenshots; Play needs 2 to 8`);
  }
  for (const name of shots) {
    const file = path.join(screenshots, name);
    assertPng(file, { colorType: PNG_RGB, screenshot: true });
    plan.set(`${locale}/images/phoneScreenshots/${name}`, fs.readFileSync(file));
  }
  return plan;
}

function listFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...listFiles(full));
    else out.push(full);
  }
  return out;
}

// Files that would change if the plan were written: added, modified, or stale.
export function diffPlayMetadata(plan, { outDir = DEFAULT_OUT_DIR, locale = DEFAULT_LOCALE } = {}) {
  const changed = [];
  for (const [relative, bytes] of plan) {
    const target = path.join(outDir, relative);
    if (!fs.existsSync(target) || !fs.readFileSync(target).equals(bytes)) changed.push(relative);
  }
  for (const existing of listFiles(path.join(outDir, locale))) {
    const relative = path.relative(outDir, existing).split(path.sep).join('/');
    if (!plan.has(relative)) changed.push(relative);
  }
  return changed.sort();
}

export function syncPlayMetadata({ storeDir = DEFAULT_STORE_DIR, outDir = DEFAULT_OUT_DIR, locale = DEFAULT_LOCALE } = {}) {
  const plan = planPlayMetadata({ storeDir, locale });
  const changed = diffPlayMetadata(plan, { outDir, locale });
  for (const existing of listFiles(path.join(outDir, locale))) {
    const relative = path.relative(outDir, existing).split(path.sep).join('/');
    if (!plan.has(relative)) fs.rmSync(existing);
  }
  for (const [relative, bytes] of plan) {
    const target = path.join(outDir, relative);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, bytes);
  }
  return { written: [...plan.keys()], changed };
}

function parseArgs(argv) {
  const options = { check: false };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--check') options.check = true;
    else if (arg === '--store') options.storeDir = path.resolve(argv[++i]);
    else if (arg === '--out') options.outDir = path.resolve(argv[++i]);
    else if (arg === '--locale') options.locale = argv[++i];
    else throw new Error(`unknown argument ${arg}`);
  }
  return options;
}

function main() {
  const { check, ...options } = parseArgs(process.argv.slice(2));
  if (check) {
    const changed = diffPlayMetadata(planPlayMetadata(options), options);
    if (changed.length > 0) {
      console.error(`Play metadata is stale; run node scripts/sync-play-metadata.mjs\n  ${changed.join('\n  ')}`);
      process.exit(1);
    }
    console.log('Play metadata is up to date.');
    return;
  }
  const { written, changed } = syncPlayMetadata(options);
  console.log(`${written.length} files in ${path.relative(REPO, options.outDir ?? DEFAULT_OUT_DIR)}; ${changed.length} changed`);
  for (const relative of changed) console.log(`  ${relative}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    main();
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  }
}
